// Los importes llegan por el webhook; las tasas por el nodo anterior.
const w = $('Webhook').first().json;
const has = (o) => o && typeof o === 'object' && Object.keys(o).length > 0;
const src = has(w.query) ? w.query : (has(w.body) ? w.body : w);

const amount = Number(src.amount) || 0;
const target = String(src.target || 'EUR').toUpperCase();
const rates = $input.first().json.rates || {};
const rate = rates[target];

if (rate === undefined) {
  return [{ json: { error: `Divisa no soportada: ${target}`, divisas: Object.keys(rates).slice(0, 20) } }];
}
return [{ json: {
  base: $input.first().json.base || 'USD',
  amount, target, rate,
  converted: Number((amount * rate).toFixed(2)),
  fecha_tasas: $input.first().json.date || null
}}];
